-- Catalogue identity only: no invented prices/specifications added to simulation data.
create table volteo_private.stock_models(slug text primary key,brand text not null,model text not null);
create table volteo_private.stock_declarations(
 dealer_id bigint not null references volteo_private.dealers(id),
 vehicle_slug text not null references volteo_private.stock_models(slug),
 trim text not null,availability text not null,reference text not null,
 updated double precision not null,valid_until double precision not null,
 primary key(dealer_id,vehicle_slug));
alter table volteo_private.stock_models enable row level security;
alter table volteo_private.stock_declarations enable row level security;
revoke all on volteo_private.stock_models,volteo_private.stock_declarations from public,anon,authenticated;
