alter function volteo_private.dispatch(text,text,jsonb,volteo_private.users) rename to dispatch_before_stock;
create function volteo_private.dispatch(p text,m text,d jsonb,u volteo_private.users) returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_variable
declare did bigint;slug text;b text;r jsonb;previous float8;stamp float8:=round(extract(epoch from clock_timestamp()),3);
begin
 if p='/pilot/availability' and m='GET' then
 return (select coalesce(jsonb_agg(jsonb_build_object('dealer_id',s.dealer_id,'vehicle_slug',s.vehicle_slug,'trim',s.trim,'availability',s.availability,'updated',s.updated,'valid_until',s.valid_until,'dealer_name',pa.data->>'name','city',pa.data->>'city') order by s.updated desc),'[]') from volteo_private.stock_declarations s join volteo_private.pilot_partners pa on pa.dealer_id=s.dealer_id join volteo_private.stock_models v on v.slug=s.vehicle_slug where s.valid_until>extract(epoch from now()) and volteo_private.active_partner(s.dealer_id) and pa.data->'brands' ? v.brand);
 end if;
 if p='/pilot/stock-models' then
  if u.id is null or u.role not in ('dealer','admin') then perform volteo_private.fail('Un compte concession validé est nécessaire','PT403');end if;
  did=case when u.role='admin' then nullif(d->>'dealer_id','')::bigint else u.dealer_id end;
  if m='GET' then return jsonb_build_object('partners',(select coalesce(jsonb_agg(jsonb_build_object('dealer_id',pa.dealer_id,'name',pa.data->>'name','brands',pa.data->'brands','active',volteo_private.active_partner(pa.dealer_id))),'[]') from volteo_private.pilot_partners pa where u.role='admin' or pa.dealer_id=u.dealer_id),'items',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from volteo_private.stock_declarations s where u.role='admin' or s.dealer_id=u.dealer_id));end if;
  if m not in ('PUT','DELETE') then perform volteo_private.fail('Méthode non autorisée','PT405');end if;
  if did is null then perform volteo_private.fail('Choisissez un établissement validé','PT403');end if;
  -- Serialize creation/reconfirmation and removal per establishment, including absent rows.
  perform 1 from volteo_private.pilot_partners where dealer_id=did for update;
  slug=volteo_private.txt(d,'vehicle_slug',1,100);
  select updated into previous from volteo_private.stock_declarations where dealer_id=did and vehicle_slug=slug;
  if previous is distinct from nullif(d->>'expected_updated','')::float8 then perform volteo_private.fail('Cette disponibilité a changé. Actualisez avant de continuer.','PT409');end if;
  if m='DELETE' then delete from volteo_private.stock_declarations where dealer_id=did and vehicle_slug=slug;return '{"ok":true}';end if;
  if not coalesce(volteo_private.active_partner(did),false) then perform volteo_private.fail('Votre établissement doit être validé et dans le périmètre du pilote','PT403');end if;
  select brand into b from volteo_private.stock_models where stock_models.slug=slug;
  if b is null or not exists(select 1 from volteo_private.pilot_partners where dealer_id=did and data->'brands' ? b) then perform volteo_private.fail('Ce modèle ne fait pas partie des marques validées pour votre établissement','PT403');end if;
  if d->'stock_ack' is distinct from 'true'::jsonb then perform volteo_private.fail('Confirmez la vérification réelle du stock');end if;
  insert into volteo_private.stock_declarations values(did,slug,volteo_private.txt(d,'trim',3,200),volteo_private.txt(d,'availability',3,300),volteo_private.txt(d,'reference',3,200),stamp,stamp+604800)
   on conflict(dealer_id,vehicle_slug) do update set trim=excluded.trim,availability=excluded.availability,reference=excluded.reference,updated=excluded.updated,valid_until=excluded.valid_until;
  return '{"ok":true}';
 end if;
 return volteo_private.dispatch_before_stock(p,m,d,u);
end$$;
revoke all on function volteo_private.dispatch(text,text,jsonb,volteo_private.users) from public,anon,authenticated;

-- Extend partner brand validation to the illustrated discovery catalogue as well.
do $$declare definition text;begin
 definition=pg_get_functiondef('volteo_private.dispatch_before_stock(text,text,jsonb,volteo_private.users)'::regprocedure);
 definition=replace(definition,'not exists(select 1 from volteo_private.vehicles where data->>''brand''=x)','not exists(select 1 from volteo_private.stock_models where brand=x)');
 execute definition;
end$$;
